defmodule Trento.Support.HttpClientTlsTest do
  # Real TLS handshakes between Trento.Support.HttpClient and a local HTTPS
  # server, one server per test, over certificate chains generated by openssl.
  # The expected results hold on every OTP: on OTP 27.1.3 the workaround makes
  # HttpClient behave like an OTP with the upstream fix (OTP-19240).
  use ExUnit.Case, async: true

  alias Trento.Support.Helpers.{TestCertificates, TlsTestServer}
  alias Trento.Support.HttpClient

  setup_all do
    dir =
      Path.join(System.tmp_dir!(), "trento-http-client-tls-#{System.unique_integer([:positive])}")

    on_exit(fn -> File.rm_rf!(dir) end)

    %{chains: TestCertificates.generate(dir)}
  end

  describe "HttpClient connects" do
    for chain <- ~w(valid gen-y intermediate-bug anchor-bug 8806-good 8806-bad 8806-bug) do
      test "to the #{chain} chain", %{chains: chains} do
        chain = chains[unquote(chain)]

        assert {:ok, %HTTPoison.Response{status_code: 200}} =
                 HttpClient.get(url(chain), [], ssl: [cacerts: chain.cacerts])
      end
    end

    test "to 127.0.0.1 when server_name_indication names the certificate's host",
         %{chains: %{"valid" => chain}} do
      port = serve(chain)

      assert {:ok, %HTTPoison.Response{status_code: 200}} =
               HttpClient.get("https://127.0.0.1:#{port}/", [],
                 ssl: [cacerts: chain.cacerts, server_name_indication: ~c"localhost"]
               )
    end
  end

  describe "HttpClient still rejects" do
    # An atom is the expected alert, a string is expected in the alert message,
    # a list holds the strings that can each be in it.
    for {chain, expected} <- [
          {"other-host", "hostname_check_failed"},
          {"untrusted-root", :unknown_ca},
          # Newer OTP releases (27.3.4.16, 29.0) reject a leaf with keyCertSign
          # for missing_basic_constraint before they check the key usage.
          {"leaf-bad-key-usage", ["key_usage_mismatch", "missing_basic_constraint"]},
          {"intermediate-no-basic-constraints", "missing_basic_constraint"},
          {"self-signed", "selfsigned_peer"},
          {"expired", :certificate_expired},
          {"8806-bug-ocsp", "key_usage_mismatch"},
          {"8806-bug-other-host", "hostname_check_failed"},
          {"8806-bug-expired", :certificate_expired}
        ] do
      test "the #{chain} chain with #{expected |> List.wrap() |> Enum.join(" or ")}",
           %{chains: chains} do
        chain = chains[unquote(chain)]

        assert_tls_failure(
          HttpClient.get(url(chain), [], ssl: [cacerts: chain.cacerts]),
          unquote(expected)
        )
      end
    end
  end

  describe "hackney without the workaround" do
    for chain <- ~w(gen-y intermediate-bug 8806-bug) do
      test "fails on the #{chain} chain only on an OTP with the bug", %{chains: chains} do
        chain = chains[unquote(chain)]
        # The options HttpClient used before the workaround
        result =
          HTTPoison.get(url(chain), [], ssl: [verify: :verify_peer, cacerts: chain.cacerts])

        if otp_with_key_usage_bug?() do
          assert_tls_failure(result, "key_usage_mismatch")
        else
          assert {:ok, %HTTPoison.Response{status_code: 200}} = result
        end
      end
    end
  end

  defp url(chain), do: "https://localhost:#{serve(chain)}/"

  defp serve(%{certfile: certfile, keyfile: keyfile}) do
    {TlsTestServer, certfile: certfile, keyfile: keyfile}
    |> start_supervised!(id: make_ref())
    |> TlsTestServer.port()
  end

  defp assert_tls_failure(result, expected) do
    assert {:error, %HTTPoison.Error{reason: {:tls_alert, {alert, message}}}} = result

    cond do
      is_atom(expected) -> assert alert == expected
      is_binary(expected) -> assert to_string(message) =~ expected
      is_list(expected) -> assert Enum.any?(expected, &(to_string(message) =~ &1))
    end
  end

  # OTP-19240 broke in 27.1.3 and 26.2.5.6 and was fixed in 27.2.2 and 26.2.5.8
  defp otp_with_key_usage_bug? do
    version =
      [:code.root_dir(), "releases", :erlang.system_info(:otp_release), "OTP_VERSION"]
      |> Path.join()
      |> File.read!()
      |> String.trim()
      |> String.split(".")
      |> Enum.map(&String.to_integer/1)

    (version >= [27, 1, 3] and version < [27, 2, 2]) or
      (version >= [26, 2, 5, 6] and version < [26, 2, 5, 8])
  end
end
